!function(e){function a(a){for(var r,i,n=a[0],o=a[1],m=a[2],c=0,g=[];c<n.length;c++)i=n[c],Object.prototype.hasOwnProperty.call(d,i)&&d[i]&&g.push(d[i][0]),d[i]=0;for(r in o)Object.prototype.hasOwnProperty.call(o,r)&&(e[r]=o[r]);for(f&&f(a);g.length;)g.shift()();return p.push.apply(p,m||[]),t()}function t(){for(var e,a=0;a<p.length;a++){for(var t,i=p[a],n=!0,o=1;o<i.length;o++)t=i[o],0!==d[t]&&(n=!1);n&&(p.splice(a--,1),e=r(r.s=i[0]))}return e}function r(a){if(i[a])return i[a].exports;var t=i[a]={i:a,l:!1,exports:{}};return e[a].call(t.exports,t,t.exports,r),t.l=!0,t.exports}var i={},d={27:0},p=[];r.m=e,r.c=i,r.d=function(e,a,t){r.o(e,a)||Object.defineProperty(e,a,{enumerable:!0,get:t})},r.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},r.t=function(e,a){if(1&a&&(e=r(e)),8&a)return e;if(4&a&&"object"==typeof e&&e&&e.__esModule)return e;var t=Object.create(null);if(r.r(t),Object.defineProperty(t,"default",{enumerable:!0,value:e}),2&a&&"string"!=typeof e)for(var i in e)r.d(t,i,function(a){return e[a]}.bind(null,i));return t},r.n=function(e){var a=e&&e.__esModule?function(){return e.default}:function(){return e};return r.d(a,"a",a),a},r.o=function(e,a){return Object.prototype.hasOwnProperty.call(e,a)},r.p="";var n=window.webpackJsonp=window.webpackJsonp||[],o=n.push.bind(n);n.push=a,n=n.slice();for(var m=0;m<n.length;m++)a(n[m]);var f=o;p.push([114,0]),t()}({114:function(e,a,t){"use strict";t.r(a);var r=t(0);Object(r.a)("de","army",t(115),t(1))},115:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"半履带装甲车辆","link":"de_army#de_army_avhtv"}],"model":"250、251系列半履带装甲炮兵观测车","description":"<p>由于253半履带装甲炮兵观测车在实战中表现不理想，且随着二战战事的发展，不断扩大的德军自行火炮与装甲部队急需更多的炮兵观测车，因此德军将不少250与251车体改装为炮兵观测车，并逐步替代了253，其中用250车体改装的有Sdkfz 250/4炮兵观测车、Sdkfz 250/5炮兵观测车、Sdkfz 250/12炮兵测绘车和Sdkfz 250/253野战改装型炮兵观测车；用251车体改装的有Sdkfz 251/12炮兵测绘与器材运载车、Sdkfz 251/13炮兵录音车、Sdkfz 251/14炮兵测声车、Sdkfz 251/15炮兵测光车和Sdkfz 251/18（Sdkfz 251/5）炮兵观测车。这些车的功能大致能分为二种，一种是为自己炮车提供打击目标的数据，指引炮车进行攻击；另一种是为自己的部队提供敌方炮火攻击的预警信号。到二战中期，炮兵观测车已基本全部配备给德军各装甲师与摩托化炮兵师下属的团、营级单位，成为德军装甲火炮部队在战场上的一种重要和必要的装备。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_avhtv25xa_11.jpg","description":"<h6>Sdkfz 250/5型半履带装甲炮兵观测车</h6><p>Sdkfz 250/5是用250早期车体改装的炮兵观测车，在1942年中期定型，它是德军用250车体最早改装的炮兵观测车，主要配备给德军摩托化炮兵部队使用（计划每团配备13辆）。该车战斗全重5.35吨，核载乘员4人，含驾驶员1 人，车长兼炮兵观测员1人，通讯员2人。武器配备为一挺MG34或MG42机枪；该车车厢内安装FuG 8和FuG 4电台各一部，采用框形（后改为星形）天线，并在驾驶员座位后面安装了一部双筒潜望镜，炮兵观测员可在车内将观测到的敌方目标的方位与坐标告知通讯员发给已方的炮兵进行射击。</p><p>后来，随着德军炮兵团换装了更先进的自行火炮与炮兵观测车，部分Sdkfz 250/5就改为配备给德军的装甲侦察部队，并改称为轻型装甲侦察车(有资料将之称为Sdkfz 250/5 Ⅱ型，而以前的称为Ⅰ型），车内电台换装为能作远程通讯的FuG 12型，车载乘员增至5人。</p>","caption":""},{"image":"imgs/de/army/de_army_avhtv25xa_12.jpg","description":"<h6>Sdkfz 250/4型半履带装甲炮兵观测车</h6><p>Sdkfz 250/4是用250后期新型车体改装的炮兵观测车，在1943年中期定型，主要装备给德军突击炮部队及各种装备近程自行火炮的部队，包括150mm10管自行火箭炮部队，给它们提供战场侦察与观测用。该车战斗全重5.7吨，核载乘员4人，配备一挺MG42型机枪，车内安装一台FuG 15型超短波接收机和一台FuG 16型发射机（功率10W），车外安装有2米星形天线，并配备了一台车长观测用的潜望镜。</p>","caption":""},{"image":"imgs/de/army/de_army_avhtv25xa_13.jpg","description":"<h6>Sdkfz 250/12型半履带装甲炮兵观测车</h6><p>Sdkfz 250/12是德军用250车体改装的最后一种正式命名的炮兵观测车，主要装备给德军摩托化炮兵团，通过该车对敌方炮火的观测，将其火炮的方位与坐标提供给已方炮车反击。该车战斗全重5.37吨，核载乘员3～5人，除驾驶员与通讯员外，还会配备一名炮兵测绘军官。该车装有一挺MG34或MG42型高射机枪（备弹1100发）。用250早期车体改装的Sdkfz 250/12安装一台FuG 8型电台，而用250后期新车体改装的Sdkfz 250/12则改为安装一台FuG 14型电台；车上配备了2台潜望镜，以方便车长作前后观测。</p><p>Sdkfz 250/12炮兵观测车的改装至1944年底结束，生产数量很少。</p>","caption":""},{"image":"imgs/de/army/de_army_avhtv25xa_14.jpg","description":"<h6>Sdkfz 250/253型半履带装甲炮兵观测车</h6><p>Sdkfz 250/253是一种非正式命名的用250车体改装的炮兵观测车，其车厢是全封闭的（与Sdkfz 253很相似），由于是属野战改装车，故没正式命名。该车在全封闭顶盖上开有二个供乘员出入的舱口，车上安装有电台和潜望镜，车外装有标准2米天线；该车未正式配备给德军部队，只在1942年夏季东线苏联战场上出现过。</p>","caption":""},{"image":"{{text}}用251 C型车体改装的251/5型半履带装甲炮兵观测车{{image}}imgs/de/army/de_army_avhtv25xa_15.jpg{{text}}用251 D型车体改装的251/18型半履带装甲炮兵观测车{{image}}imgs/de/army/de_army_avhtv25xa_16.jpg","description":"<h6>Sdkfz 251/18（251/5）型半履带装甲炮兵观测车</h6><p>1943年前德军用251 C型车体改装了一批炮兵观测车，称为251/5，到了1943年，德军将所有用251车体改装的炮兵观测车正式命名为Sdkfz 250/18，并改用251 D型车体改装，装备给装甲师属独立装甲炮兵团和一些自行火炮营，逐步替代车体狭小的250系列炮兵观测车，Sdkfz 250/18主要作用是跟随装甲火炮部队作战，在战场上观测确定敌军集群或防御设施，引导已方火炮射击以进行火力支援。该车车内安装有2部大功率电台（有些还会保留一台小功率电台）和一台潜望镜，并根据安装电台型号组别的不同分为4类。</p><p>Sdkfz 250/18炮兵观测车的改装一直至1945年3月为止，共改装了180辆。</p>","caption":""},{"image":"imgs/de/army/de_army_avhtv25xa_17.jpg","description":"<h6>Sdkfz 251/12型半履带装甲炮兵测绘与器材运载车</h6><p>251/12是1942年开始进行样车测试的一种用251 C型车体改装的炮兵测绘与器材运载车，是配备给一些炮兵测绘部队使用的特殊装备。该车核载乘员6人，除1名驾驶员和2名通讯员外，还专门配属了1名炮兵观测军官和2名炮兵测绘人员。并在车内配备了炮兵观测和测绘用的双筒潜望镜和炮兵角度测量器，并配备了通讯用电台与天线，它经常与Sdkfz 251/12炮兵测绘与器材车、Sdkfz 251/13炮兵录音车、Sdkfz 251/14炮兵测声车、Sdkfz 251/15炮兵测光车等其中的一辆或多辆特种车辆组成火炮观测组，通过声、光等手段对敌方火炮阵地进行定位，并在最短时间内提供给已方的火炮进行反击。</p>","caption":""}],"part2title":"战场上的250、251系列半履带装甲炮兵观测车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_avhtv25xa_21.jpg","description":"1942年11月，西线战场法国马赛地区，隶属德军第10装甲师第90装甲炮兵团第5炮兵连的一辆Sdkfz 250/5 Alt半履带装甲炮兵观测车。","caption":""},{"image":"imgs/de/army/de_army_avhtv25xa_22.jpg","description":"1944年改作侦察装甲车使用的一辆Sdkfz 250/5半履带装甲炮兵观测车。","caption":""},{"image":"imgs/de/army/de_army_avhtv25xa_23.jpg","description":"1943年夏天，东线苏联战场，德军某装甲师属装甲炮兵团下属的一辆Sdkfz 250/5 Alt半履带装甲炮兵观测车。","caption":""},{"image":"imgs/de/army/de_army_avhtv25xa_24.jpg","description":"1944年4月，一辆不明单位的德军装甲师属装甲炮兵团的Sdkfz 250/4 Neu半履带装甲炮兵观测车，正与德军装甲炮兵部队的车辆一起行驶穿过一村庄。","caption":""},{"image":"imgs/de/army/de_army_avhtv25xa_25.jpg","description":"1944年，德军一辆Sdkfz 250/4 Neu半履带装甲炮兵观测车的车组乘员正在用树枝为车体作伪装掩护。","caption":""},{"image":"imgs/de/army/de_army_avhtv25xa_26.jpg","description":"1943年冬天，东线苏联战场，一辆隶属德国武装党卫军炮兵部队的Sdkfz 250/12 Alt半履带装甲炮兵观测车正驶过一个俄罗斯村庄，由于是在行进中，该车收起了潜望镜，并在车厢前部用高射机枪吊架安装了一挺MG34机枪，以作行进中的警戒。","caption":""},{"image":"imgs/de/army/de_army_avhtv25xa_27.jpg","description":"1942年8月，一辆德军Sdkfz 250/253型半履带装甲炮兵观测车与其所属的装甲炮兵部队在东线苏联战场南部平原上集结。","caption":""},{"image":"imgs/de/army/de_army_avhtv25xa_28.jpg","description":"一名德军正在为一辆Sdkfz 250/253型半履带装甲炮兵观测车涂上伪装图案。","caption":""},{"image":"imgs/de/army/de_army_avhtv25xa_29.jpg","description":"二战初期，东线苏联战场，德军一辆正在草原上行进的Sdkfz 251/5（Sdkfz 251/18）半履带装甲炮兵观测车。","caption":""},{"image":"imgs/de/army/de_army_avhtv25xa_30.jpg","description":"1942年冬天，东线苏联战场，德军一辆Sdkfz 251/5（Sdkfz 251/18）半履带装甲炮兵观测车的一名车组乘员正站在车上观测目标。","caption":""},{"image":"imgs/de/army/de_army_avhtv25xa_31.jpg","description":"一辆德军Sdkfz 251/18 型半履带装甲炮兵观测车上正在进行观测的两名车组成员，1名在车中用潜望镜上观测，另1名则站在车上用望远镜进行观察，图中可清楚看到安装在车上的MG34型机枪。","caption":""},{"image":"imgs/de/army/de_army_avhtv25xa_32.jpg","description":"1944年春天，停在西线战场某地的德国武装党卫军炮兵测绘部队的一辆Sdkfz 251/15 Ausf D型半履带装甲炮火测光车，车前的一群德军军官可能是该部队的指挥官和技术军官。","caption":""}]}')}});